class TokenBucket {
  constructor({ capacity, refillPerSecond, now = Date.now }) {
    if (typeof capacity !== 'number' || capacity <= 0 || !Number.isFinite(capacity)) {
      throw new RangeError('capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || refillPerSecond < 0) {
      throw new RangeError('refillPerSecond must be a non-negative number');
    }

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.nowFunc = now;

    // Başlangıçta kova dolu başlar
    this.tokens = capacity;
    this.lastRefillTime = this.nowFunc();
  }

  _refill() {
    const currentTime = this.nowFunc();
    const elapsedMs = currentTime - this.lastRefillTime;

    // Saat geri giderse veya aynı saniyedeyse işlem yapma
    if (elapsedMs <= 0) return;

    // Geçen süreye göre eklenecek jeton miktarı: (saniye * refillPerSecond)
    const tokensToAdd = (elapsedMs / 1000) * this.refillPerSecond;

    this.tokens = Math.min(this.capacity, this.tokens + tokensToAdd);
    this.lastRefillTime = currentTime;
  }

  tryTake(n = 1) {
    if (typeof n !== 'number' || n <= 0 || !Number.isFinite(n)) {
      throw new RangeError('n must be a positive finite number');
    }

    this._refill();

    // Hassasiyet sorunlarını önlemek için çok küçük farklar ihmal edilebilir ancak 
    // standart gereği doğrudan karşılaştırma yapıyoruz.
    if (this.tokens >= n) {
      this.tokens -= n;
      return true;
    }
    return false;
  }

  available() {
    this._refill();
    return this.tokens;
  }

  msUntil(n = 1) {
    if (typeof n !== 'number' || n <= 0 || !Number.isFinite(n)) {
      throw new RangeError('n must be a positive finite number');
    }

    this._refill();

    if (this.tokens >= n) {
      return 0;
    }

    // Eğer dolum hızı 0 ise ve jeton yetmiyorsa sonsuz bekleyiş
    if (this.refillPerSecond <= 0) {
      return Infinity;
    }

    // Kapasite, istenen miktardan küçükse asla ulaşılamaz
    if (n > this.capacity) {
      return Infinity;
    }

    const needed = n - this.tokens;
    // ms = (ihtiyaç duyulan jeton / saniyede gelen jeton) * 1000
    const msNeeded = (needed / this.refillPerSecond) * 1000;
    return Math.ceil(msNeeded);
  }
}

module.exports = { TokenBucket };

