node -e "const { TokenBucket } = require('./kova.js');
async function test() {
  let currentTime = 1000;
  const now = () => currentTime;

  // Test 1: Başlangıç durumu (Dolu kova)
  const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 2, now });
  console.assert(bucket.available() === 10, 'Test 1 Fail: Kova dolu başlamalı');

  // Test 2: tryTake başarılı
  console.assert(bucket.tryTake(5) === true, 'Test 2 Fail: 5 jeton alınabilmeli');
  console.assert(Math.abs(bucket.available() - 5) < 0.001, 'Test 2 Fail: Kalan jeton 5 olmalı');

  // Test 3: tryTake başarısız (yetersiz jeton)
  console.assert(bucket.tryTake(6) === false, 'Test 3 Fail: Yetersiz jetonla false dönmeli');
  console.assert(Math.abs(bucket.available() - 5) < 0.001, 'Test 3 Fail: Jetonlar azalmamalı');

  // Test 4: Zaman geçince dolum (2 saniye geçerse 2*2=4 jeton gelir)
  currentTime += 2000;
  console.assert(Math.abs(bucket.available() - 9) < 0.001, 'Test 4 Fail: Dolum yanlış');

  // Test 5: msUntil (3 jeton için gereken süre)
  // Şu anki jeton: 9. Hedef: 12 (ama kapasite 10). n > capacity durumu kontrolü.
  console.assert(bucket.msUntil(11) === Infinity, 'Test 5 Fail: Kapasite üstü Infinity olmalı');

  // Test 6: msUntil normal durum
  // Mevcut jeton 9. Hedef 10. Gereken 1 jeton. Hız 2/sn -> 0.5 sn = 500ms.
  currentTime += 0; // Zamanı sabitleyelim (refill yapmasın)
  console.assert(bucket.msUntil(10) === 500, 'Test 6 Fail: msUntil yanlış');

  // Test 7: Saat geri giderse
  currentTime -= 5000;
  bucket._refill(); // Manuel tetikleme simülasyonu (internal check)
  console.assert(bucket.available() === 9, 'Test 7 Fail: Saat geri giderse jeton azalmamalı');

  // Test 8: Hata fırlatma
  try { bucket.tryTake(-1); console.error('Test 8 Fail: Negatif n hata vermeli'); } catch (e) { console.assert(e instanceof RangeError, 'Test 8 Fail: Yanlış hata tipi'); }

  console.log('Tüm testler başarıyla tamamlandı!');
}
test().catch(err => { console.error(err); process.exit(1); });"

